@Test
void abortWhilePermissionIsPendingFinishesAsAborted() throws Exception {
    var provider = new ScriptedModelProvider().enqueue(List.of(
            new ScriptedModelProvider.Step.Tool("call-1", "echo", Map.of("value", "hello")),
            new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.TOOL_USE)));
    var permission = new CompletableFuture<PermissionDecider.Decision>();
    var requested = new AtomicReference<PermissionDecider.Request>();
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
            .tool(ToolDefinition.sync("echo", "Echo input", Map.of("type", "object"),
                    (arguments, cancellation) -> ToolDefinition.ToolResult.text("unexpected")))
            .permissionDecider(request -> {
                requested.set(request);
                return permission;
            }).idGenerator(new SequentialIds()).build()) {
        AgentSession session = runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."));
        var run = session.prompt("wait for permission");
        long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
        while (requested.get() == null && System.nanoTime() < deadline) Thread.onSpinWait();
        assertTrue(requested.get() != null, "permission request was not emitted");
        assertTrue(run.abort());
        assertEquals(io.github.diodeme.ji.agent.AgentEvent.Outcome.ABORTED,
                run.completion().toCompletableFuture().get(5, TimeUnit.SECONDS).outcome());
        assertEquals(2, session.transcript().size());
    }
}

